package net.civeira.phylax.feature.oauth.delegatelogin.domain;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.HexFormat;

import io.quarkus.runtime.annotations.RegisterForReflection;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

/**
 * A delegated login started by one browser and not yet completed.
 *
 * Responsibilities: - Remember which tenant, client and provider started the login. - Bind the
 * login to the browser that started it and to the provider request that was sent.
 *
 * Design notes: - Stored server side under the hash of its {@code state}; the browser only keeps
 * the binding secret in an HttpOnly cookie. - Consumed once: a second completion with the same
 * {@code state} finds nothing.
 */
@Getter
@Builder
@NoArgsConstructor
@AllArgsConstructor
@RegisterForReflection
public class PendingDelegation {
  /**
   * Random bytes for state, binding and code verifier.
   */
  private static final int SECRET_BYTES = 32;
  /**
   * Shared random source.
   */
  private static final SecureRandom RANDOM = new SecureRandom();

  /**
   * Tenant name that started the login.
   */
  private String tenant;
  /**
   * Provider name (its identifier within the tenant).
   */
  private String provider;
  /**
   * Client that requested the authorization.
   */
  private String clientId;
  /**
   * Relative URL of the authorize request to resume.
   */
  private String returnPath;
  /**
   * Callback URL registered at the provider (redirect URI or ACS URL).
   */
  private String callbackUrl;
  /**
   * SHA-256 of the browser binding secret.
   */
  private String bindingHash;
  /**
   * PKCE verifier sent to OAuth providers.
   */
  private String codeVerifier;
  /**
   * ID of the SAML AuthnRequest; the response must answer this request.
   */
  private String requestId;
  /**
   * Epoch millis when the login started.
   */
  private long createdAt;

  /**
   * Creates a new random secret (state or binding).
   *
   * @return URL-safe random value
   */
  public static String newSecret() {
    byte[] bytes = new byte[SECRET_BYTES];
    RANDOM.nextBytes(bytes);
    return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
  }

  /**
   * Hashes a secret so that only its digest is stored.
   *
   * @param secret raw value
   * @return lowercase hex SHA-256
   */
  public static String hash(String secret) {
    try {
      MessageDigest digest = MessageDigest.getInstance("SHA-256");
      return HexFormat.of().formatHex(digest.digest(secret.getBytes(StandardCharsets.UTF_8)));
    } catch (NoSuchAlgorithmException ex) {
      throw new IllegalStateException("SHA-256 not available", ex);
    }
  }

  /**
   * The SAML AuthnRequest ID for a state: an NCName, so it starts with an underscore.
   *
   * @param state login state
   * @return request ID
   */
  public static String requestIdFor(String state) {
    return "_" + hash("saml-authn-request|" + state);
  }

  /**
   * Checks the browser binding in constant time.
   *
   * @param binding value of the binding cookie
   * @return true when the cookie belongs to the browser that started the login
   */
  public boolean boundTo(String binding) {
    if (binding == null || binding.isEmpty() || bindingHash == null) {
      return false;
    }
    return MessageDigest.isEqual(hash(binding).getBytes(StandardCharsets.UTF_8),
        bindingHash.getBytes(StandardCharsets.UTF_8));
  }

  /**
   * Checks that the completion comes from the same tenant, provider and client.
   *
   * @param tenantName tenant of the completing request
   * @param providerName provider sent by the completing request
   * @param client client of the completing request
   * @return true when all of them match
   */
  public boolean sameFlow(String tenantName, String providerName, String client) {
    return tenant != null && tenant.equals(tenantName) && provider != null
        && provider.equals(providerName) && clientId != null && clientId.equals(client);
  }
}
